function renderBusiness(full=false){adapter?.setPlayback?.({paused,speed});renderService();renderTutorial();renderAwareness();renderOpeningOutlook();renderDelivery();if(full||activeTab==='storage')renderStorage();if(full||activeTab==='finance')renderFinance();if(full){renderOperatingSettings();renderMenu();renderStock();renderStaff();renderReport();renderGrowth()}else for(const[id,item]of Object.entries(Business.STOCK_ITEMS)){if($(`stock-${id}`))$(`stock-${id}`).textContent=`${business.stock[id]} ${item.unit}`;if($(`stockbar-${id}`))$(`stockbar-${id}`).style.width=`${Math.min(100,business.stock[id]/(id==='beans'?80:40)*100)}%`}renderResearchProgress();renderPeople($('plan'),business);adapter?.updateBusiness?.(business)}
