$('openDay').onclick=startDay;$('nextDay').onclick=startDay;$('closeDay').onclick=()=>{if(Business.requestClose)action(s=>Business.requestClose(s))};$('pause').onclick=()=>{paused=!paused;elapsed=0;lastTime=performance.now();persistBusiness();renderBusiness();message(paused?'営業の時間を一時停止しました。':'営業の時間を再開しました。')};$('speed').onchange=e=>{speed=Number(e.target.value);adapter?.setPlayback?.({paused,speed});message(`営業の時間を${speed}倍速にしました。`)};
