function startupMessage(business){if(business.phase==='open')return '前回の営業を一時停止で再開しました。▶ で続きを始められます。';if(business.phase==='closed')return `${business.day}日目の閉店後データを復元しました。帳簿と在庫を確認して、翌日の準備をしましょう。`;return '開店準備のデータを表示しています。仕入れ・メニュー・スタッフを確認して、お店を開けましょう。'}
