setInterval(()=>{const now=performance.now(),delta=Math.min(1000,now-lastTime);lastTime=now;if(paused||document.hidden||business.phase!=='open')return;elapsed+=delta*speed/1000;const minutes=Math.floor(elapsed);if(!minutes)return;elapsed-=minutes;try{const before=business.phase,researchBefore=business.progression.research?.recipeId;business=Business.advanceTime(business,store.state,minutes,m);const done=before!==business.phase;renderBusiness(done||researchBefore!==business.progression.research?.recipeId);if(researchBefore&&researchBefore!==business.progression.research?.recipeId)message(`${Business.MENU[researchBefore].name}の開発が完了しました。閉店後に仕入れと販売設定をして、新しい味を届けましょう。`);if(done){lastPhase=business.phase;paused=true;renderLayout();persistBusiness();message(business.lastEvent);tab('report')}else if(business.minute%5<minutes)persistBusiness()}catch(e){paused=true;persistBusiness();message(`営業を一時停止しました: ${e.message}`,true);renderBusiness()}},400);
